INSERT INTO `warning_letter_template_versions` (`version_id`, `template_id`, `version_number`, `subject_template`, `body_template`, `html_template`, `source_filename`, `source_docx_bytes`, `placeholders_used`, `change_note`, `created_by`, `created_at`) VALUES (9,8,1,'Official {{warning_level}}: {{policy_reference}} ({{case_reference}})','Dear {{resident_name}},\n\nThis {{warning_level}} is issued by the Office of the Subdivision Leader of {{subdivision_name}} concerning case {{case_reference}}. On {{incident_date}}, an incident involving {{pet_name}} ({{pet_type}}), an animal in your care at {{resident_address}}, was reported to the subdivision and verified.\n\nViolation Details\n{{violation_description}}\n\nApplicable Subdivision Policy\n{{policy_reference}}\n\nRequired Corrective Action\n{{required_action}}\n\nPlease carry out the corrective action stated above. If you have questions, or wish to explain your side, contact the Office of the Subdivision Leader and mention warning reference {{warning_reference}}. Repeated violations of the same policy may lead to a higher warning level under the subdivision\'s rules.\n\nThis letter was issued on {{issue_date}}.','<div class=\"ss-warning-letter\">\n  <div class=\"ss-warning-letter__header\">\n    <div>\n      <div class=\"ss-warning-letter__org\">StraySafe Subdivision</div>\n      <div class=\"ss-warning-letter__sub\">Office of the Subdivision Leader</div>\n    </div>\n    <div class=\"ss-warning-letter__refs\">\n      <span><strong>Warning Reference:</strong> {{warning_reference}}</span>\n      <span><strong>Case Reference:</strong> {{case_reference}}</span>\n    </div>\n  </div>\n  <h2 class=\"ss-warning-letter__subject\">Official {{warning_level}}: {{policy_reference}} ({{case_reference}})</h2>\n  <div class=\"ss-warning-letter__body\"><p>Dear {{resident_name}},</p>\n<p>This {{warning_level}} is issued by the Office of the Subdivision Leader of {{subdivision_name}} concerning case {{case_reference}}. On {{incident_date}}, an incident involving {{pet_name}} ({{pet_type}}), an animal in your care at {{resident_address}}, was reported to the subdivision and verified.</p>\n<p>Violation Details<br/>{{violation_description}}</p>\n<p>Applicable Subdivision Policy<br/>{{policy_reference}}</p>\n<p>Required Corrective Action<br/>{{required_action}}</p>\n<p>Please carry out the corrective action stated above. If you have questions, or wish to explain your side, contact the Office of the Subdivision Leader and mention warning reference {{warning_reference}}. Repeated violations of the same policy may lead to a higher warning level under the subdivision&#x27;s rules.</p>\n<p>This letter was issued on {{issue_date}}.</p></div>\n</div>',NULL,NULL,'[\"warning_level\", \"policy_reference\", \"case_reference\", \"resident_name\", \"subdivision_name\", \"incident_date\", \"pet_name\", \"pet_type\", \"resident_address\", \"violation_description\", \"required_action\", \"warning_reference\", \"issue_date\"]','Initial version (inserted by Claude Code at the developer\'s request)',1,'2026-11-18 19:52:59');
