INSERT INTO `generated_warning_letters` (`letter_id`, `warning_reference`, `subdivision_id`, `warning_id`, `complaint_step_id`, `report_id`, `case_reference`, `recipient_user_id`, `recipient_name`, `recipient_address`, `pet_id`, `pet_name`, `pet_type`, `warning_level`, `policy_id`, `policy_reference`, `template_id`, `template_name`, `template_version_id`, `template_version_number`, `rendered_subject`, `rendered_body`, `rendered_html`, `placeholders_json`, `issued_by`, `issued_by_name`, `issued_at`, `notification_id`, `notification_status`, `notification_error`, `notification_created_at`, `notification_sent_at`, `viewed_at`, `retry_count`, `last_retry_at`, `created_at`, `updated_at`) VALUES (1,'WARN-2026-0001',1,NULL,1,3,'SS-2026-0003',4,'Emmanuel Vito Cruz','Block 2, Lot 3, 14 Dama de Noche, Brgy. Cutcut, Guiguinto, Bulacan, Central Luzon, 1100',1,'Mochi','Dog','1st Warning','pol-mwhxoz73','Selera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog',1,'Standard Subdivision Warning Letter',1,1,'1st Warning (WARN-2026-0001) — SS-2026-0003','Selera Homes — Office of the Subdivision Leader\n\nDate Issued: November 17, 2026\nWarning Reference: WARN-2026-0001\nCase Reference: SS-2026-0003\n\nTO: Emmanuel Vito Cruz\nAddress: Block 2, Lot 3, 14 Dama de Noche, Brgy. Cutcut, Guiguinto, Bulacan, Central Luzon, 1100\n\nSUBJECT: Official 1st Warning Regarding Selera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog\n\nDear Emmanuel Vito Cruz,\n\nThis official 1st Warning is issued regarding an animal incident recorded under SS-2026-0003 on November 17, 2026 at 8:50 PM involving Mochi (Dog).\n\nViolation Details:\nNananahol ng lumalapit sakanya\n\nApplicable Subdivision Policy:\nSelera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog\n\nRequired Corrective Action:\nPet owners are responsible for keeping their dogs and cats under control within the subdivision. Pets must not be allowed to roam freely, damage other residents\' property, create disturbances, or pose safety risks to other residents.\n\nPlease address this matter promptly. Failure to comply or repeated violations may result in further escalation in accordance with subdivision rules and local ordinances.\n\nIssued by:\nLeilah (Subdivision Leader)\nSelera Homes','<div class=\"ss-warning-letter\">\n  <div class=\"ss-warning-letter__header\">\n    <div>\n      <div class=\"ss-warning-letter__org\">Selera Homes</div>\n      <div class=\"ss-warning-letter__sub\">Office of the Subdivision Leader · Official Warning Letter</div>\n    </div>\n    <div class=\"ss-warning-letter__refs\">\n      <span><strong>Warning Ref:</strong> WARN-2026-0001</span>\n      <span><strong>Case Ref:</strong> SS-2026-0003</span>\n    </div>\n  </div>\n  <h2 class=\"ss-warning-letter__subject\">1st Warning (WARN-2026-0001) — SS-2026-0003</h2>\n  <div class=\"ss-warning-letter__body\"><p>Selera Homes — Office of the Subdivision Leader</p>\n<p>Date Issued: November 17, 2026<br/>Warning Reference: WARN-2026-0001<br/>Case Reference: SS-2026-0003</p>\n<p>TO: Emmanuel Vito Cruz<br/>Address: Block 2, Lot 3, 14 Dama de Noche, Brgy. Cutcut, Guiguinto, Bulacan, Central Luzon, 1100</p>\n<p>SUBJECT: Official 1st Warning Regarding Selera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog</p>\n<p>Dear Emmanuel Vito Cruz,</p>\n<p>This official 1st Warning is issued regarding an animal incident recorded under SS-2026-0003 on November 17, 2026 at 8:50 PM involving Mochi (Dog).</p>\n<p>Violation Details:<br/>Nananahol ng lumalapit sakanya</p>\n<p>Applicable Subdivision Policy:<br/>Selera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog</p>\n<p>Required Corrective Action:<br/>Pet owners are responsible for keeping their dogs and cats under control within the subdivision. Pets must not be allowed to roam freely, damage other residents&#x27; property, create disturbances, or pose safety risks to other residents.</p>\n<p>Please address this matter promptly. Failure to comply or repeated violations may result in further escalation in accordance with subdivision rules and local ordinances.</p>\n<p>Issued by:<br/>Leilah (Subdivision Leader)<br/>Selera Homes</p></div>\n</div>','{\"pet_name\": \"Mochi\", \"pet_type\": \"Dog\", \"issued_by\": \"Leilah (Subdivision Leader)\", \"issue_date\": \"November 17, 2026\", \"summons_date\": \"\", \"incident_date\": \"November 17, 2026 at 8:50 PM\", \"resident_name\": \"Emmanuel Vito Cruz\", \"summons_place\": \"\", \"warning_level\": \"1st Warning\", \"case_reference\": \"SS-2026-0003\", \"required_action\": \"Pet owners are responsible for keeping their dogs and cats under control within the subdivision. Pets must not be allowed to roam freely, damage other residents\' property, create disturbances, or pose safety risks to other residents.\", \"observation_days\": \"\", \"policy_reference\": \"Selera Homes Homeowners Association (HOA) House Rules and Regulations – Pet Ownership and Control Section. — Uncontrolled roaming dog\", \"resident_address\": \"Block 2, Lot 3, 14 Dama de Noche, Brgy. Cutcut, Guiguinto, Bulacan, Central Luzon, 1100\", \"subdivision_name\": \"Selera Homes\", \"warning_reference\": \"WARN-PENDING\", \"violation_description\": \"Nananahol ng lumalapit sakanya\"}',1,'Leilah (Subdivision Leader)','2026-11-17 21:30:08',10,'sent',NULL,'2026-11-17 21:30:32','2026-11-17 21:30:32','2026-11-17 21:31:36',0,NULL,'2026-11-17 21:30:07','2026-11-17 21:31:35');
